// `@vizejs/native`'s generated NAPI surface must come from exactly one file: the
// `index.d.ts` that `napi build` generates from the `#[napi]` items in
// `crates/vize_vitrine`. A hand-written second copy cannot be kept in sync --
// `npm/native/types/` drifted until its `SfcCompileOptionsNapi` was missing four
// fields and its `BatchCompileOptionsNapi` eight, while `package.json` shipped
// the directory and no test compared it to the generated file (#3494).
//
// A shipped declaration that is silently a subset of the real API is worse than
// no declaration: valid option objects look like type errors. These tests pin
// that there is one generated authority. The handwritten portable JS projection
// helper has its own exact allowlist and must never copy a generated NAPI type.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import os from "node:os";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const nativeDir = path.join(root, "npm/native");
const require = createRequire(import.meta.url);

/** Every `.d.ts` under `npm/native`, repo-relative and sorted. Skips installed dependencies. */
function declarationFiles(dir: string, prefix: string): string[] {
  const found: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name.startsWith(".")) continue;
    const relative = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
    if (entry.isDirectory()) {
      found.push(...declarationFiles(path.join(dir, entry.name), relative));
    } else if (entry.name.endsWith(".d.ts")) {
      found.push(relative);
    }
  }
  return found.sort();
}

test("npm/native retains one generated NAPI authority and one portable helper", () => {
  assert.deepEqual(declarationFiles(nativeDir, ""), ["index.d.ts", "language-projection.d.ts"]);
  const generated = fs.readFileSync(path.join(nativeDir, "index.d.ts"), "utf8");
  const portable = fs.readFileSync(path.join(nativeDir, "language-projection.d.ts"), "utf8");
  assert.match(generated, /^\/\* auto-generated by NAPI-RS \*\//);
  assert.doesNotMatch(portable, /auto-generated by NAPI-RS/);
  const names = (source: string) =>
    [
      ...source.matchAll(
        /\bexport\s+(?:declare\s+)?(?:function|class|interface|type|const)\s+([\w$]+)/g,
      ),
    ]
      .map((match) => match[1])
      .sort();
  assert.deepEqual(
    names(portable),
    [
      "LanguageFeature",
      "LanguageProjection",
      "ProjectionDiagnostic",
      "applyDiagnosticDirectives",
      "mapLanguageDiagnosticRange",
      "toUtf16LanguageProjection",
    ].sort(),
  );
  const napiNames = new Set(names(generated));
  for (const name of names(portable))
    assert(!napiNames.has(name), `${name} duplicates the NAPI authority`);
  const runtime = require(path.join(nativeDir, "language-projection.js"));
  assert.deepEqual(
    Object.keys(runtime).sort(),
    [
      "LanguageFeature",
      "applyDiagnosticDirectives",
      "mapLanguageDiagnosticRange",
      "toUtf16LanguageProjection",
    ].sort(),
  );
});

test("npm/native ships the exact generated and portable helper closure", () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(nativeDir, "package.json"), "utf8")) as {
    files: string[];
    types: string;
  };

  assert.deepEqual(manifest.files, [
    "index.js",
    "index.d.ts",
    "language-projection.js",
    "language-projection.d.ts",
    "native-binding.js",
    "native-binding-identity.js",
    "native-targets.js",
  ]);
  assert.equal(manifest.types, "index.d.ts");
});

test("portable projection types preserve payloads and reject invalid geometry and feature types", () => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), "vize-native-projection-types-"));
  try {
    const filename = path.join(directory, "projection.ts");
    fs.writeFileSync(
      filename,
      `
import { LanguageFeature, toUtf16LanguageProjection, applyDiagnosticDirectives, mapLanguageDiagnosticRange,
  type LanguageProjection } from ${JSON.stringify(path.join(nativeDir, "language-projection.js"))};
import { getVueLanguageProjectMetadata, type VueLanguageProjectMetadata } from ${JSON.stringify(path.join(nativeDir, "index.js"))};
const project: VueLanguageProjectMetadata = getVueLanguageProjectMetadata("");
const identity: string = project.configIdentity;
const watches: string[] = project.watchedFiles;
// @ts-expect-error The metadata API accepts an explicit config path, not an options object.
getVueLanguageProjectMetadata({ configFileName: "tsconfig.json" });
// @ts-expect-error Metadata paths are strings, not transform options.
const badWatches: boolean[] = project.watchedFiles;
const projection = toUtf16LanguageProjection("", "{}");
const result = applyDiagnosticDirectives(projection, [{start: 0, payload: "preserved"}]);
const payload: string = result.diagnostics[0]!.payload;
const fidelity: "exact" | "atom" | "approximate" | "none" = mapLanguageDiagnosticRange(projection, 0, 1).fidelity;
// @ts-expect-error Native masks are numeric, not booleans.
const badFeature: boolean = LanguageFeature.Rename;
// @ts-expect-error Published feature constants are readonly.
LanguageFeature.Hover = 1;
// @ts-expect-error The protocol has exactly three span kinds.
const badKind: LanguageProjection["mappings"][number] = [0, 1, 0, 1, 3, 0];
// @ts-expect-error Source text cannot be replaced by a numeric offset.
toUtf16LanguageProjection(1, "{}");
// @ts-expect-error Diagnostic geometry uses numbers.
mapLanguageDiagnosticRange(projection, 0, "1");
// @ts-expect-error Source diagnostics cannot silently accept string positions.
applyDiagnosticDirectives(projection, [{start: "0"}]);
void payload; void fidelity;
`,
    );
    const checked = spawnSync(
      process.execPath,
      [
        require.resolve("typescript/bin/tsc"),
        "--ignoreConfig",
        "--strict",
        "--noEmit",
        "--module",
        "NodeNext",
        "--moduleResolution",
        "NodeNext",
        "--target",
        "ESNext",
        filename,
      ],
      { encoding: "utf8" },
    );
    assert.equal(checked.status, 0, checked.stdout + checked.stderr);
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
});
